style.css:
@-moz-document domain("verifactu.zimasoft.es") {
.contenedor-tpvtactil {
    width: unset;
    display: flex;
    flex-direction: column;
  }

  .tpvtactil-top-top {
    order: 0;
  }
  
  .lineas-tpvtactil td {
    color:  #000;
    font-size: 18px;
  }

  .lineas-tpvtactil input {
    color:  #000;
    font-size: 18px;
  }
  
  .lineas-tpvtactil tr:nth-child(even) {
    background-color: #fff
  }
  
  .tpv-tactil-total {
    font-size: 18px
  }
  
  .tpvtactil-mid {
    order: 2;
  }
  
  .tpvtactil-bot2 {
    order: 1;
  }
  
  .tpvtactil-bot2 div:nth-child(2) {
    height: 0px;
  }

  #ctl00_ctl00_MainContent_PanelContent_liAccionImprimirCuenta {
    display: none;
  }
}
